"use client";

import dynamic from "next/dynamic";
import { useRouter } from "next/navigation";
import type React from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { UmamiEvents, useUmami } from "@/hooks/useUmami";
import type { Experiment } from "@/lib/experiments";
import { useCursor } from "./cursor/Context";
import { ExperimentGridCard } from "./experiments/ExperimentGridCard";
import { ExperimentListItem } from "./experiments/ExperimentListItem";

const InteractivePreviewMedia = dynamic(
  () =>
    import("./experiments/InteractivePreviewMedia").then(
      (mod) => mod.InteractivePreviewMedia
    ),
  { ssr: false }
);

const ExperimentPreviewDrawer = dynamic(
  () =>
    import("./experiments/ExperimentPreviewDrawer").then(
      (mod) => mod.ExperimentPreviewDrawer
    ),
  { ssr: false }
);

interface ExperimentDrawerListProps {
  experiments: Experiment[];
  viewMode: "list" | "grid";
}

const lerp = (start: number, end: number, factor: number) => {
  return start + (end - start) * factor;
};

// Cached date formatter options for performance
const dateFormatOptions: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "long",
  day: "numeric",
};

// Pre-compute formatted date from ISO string
const formatDate = (isoDate: string): string => {
  return new Date(isoDate).toLocaleDateString("en-US", dateFormatOptions);
};

/**
 * Displays a list of experiments in either grid or list view with a preview drawer.
 * Refactored into smaller, focused components for better maintainability.
 */
export function ExperimentDrawerList({
  experiments,
  viewMode,
}: ExperimentDrawerListProps) {
  const router = useRouter();
  const [selectedExperiment, setSelectedExperiment] =
    useState<Experiment | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [mobilePreviewExperiment, setMobilePreviewExperiment] =
    useState<Experiment | null>(null);
  const touchStartRef = useRef<number | null>(null);
  /** Slug of experiment we just swiped; used to suppress only that gesture's synthetic click, not taps on other cards */
  const swipedExperimentSlugRef = useRef<string | null>(null);
  const swipeResetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const prefetchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const { setIsHidden } = useCursor();

  const PREFETCH_HOVER_DELAY_MS = 100;

  // Analytics
  const { trackExperiment, track } = useUmami();

  // Hover state for list items
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  // Use REFs for animation values to avoid re-renders
  const mousePositionRef = useRef({ x: 0, y: 0 });
  const smoothPositionRef = useRef({ x: 0, y: 0 });
  const listOriginRef = useRef({ x: 0, y: 0 });

  const [isVisible, setIsVisible] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);
  const previewRef = useRef<HTMLDivElement>(null);
  const animationRef = useRef<number | null>(null);
  const isAnimatingRef = useRef(false);

  const startAnimation = useCallback(() => {
    if (isAnimatingRef.current) {
      return;
    }
    isAnimatingRef.current = true;

    const animate = () => {
      const target = mousePositionRef.current;
      const current = smoothPositionRef.current;

      const nextX = lerp(current.x, target.x, 0.15);
      const nextY = lerp(current.y, target.y, 0.15);

      smoothPositionRef.current = { x: nextX, y: nextY };

      if (previewRef.current) {
        const origin = listOriginRef.current;
        previewRef.current.style.transform = `translate3d(${nextX + 20}px, ${nextY - 100}px, 0)`;
        previewRef.current.style.left = `${origin.x}px`;
        previewRef.current.style.top = `${origin.y}px`;
      }

      if (
        Math.abs(target.x - nextX) < 0.5 &&
        Math.abs(target.y - nextY) < 0.5
      ) {
        isAnimatingRef.current = false;
        animationRef.current = null;
        return;
      }

      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);
  }, []);

  // Memoize formatted dates to avoid recalculating on each render
  const formattedDates = useMemo(() => {
    return new Map(
      experiments.map((exp) => [exp.slug, formatDate(exp.created)])
    );
  }, [experiments]);

  // Hide custom cursor when drawer is open
  useEffect(() => {
    setIsHidden(isOpen);
  }, [isOpen, setIsHidden]);

  // Prefetch when drawer opens (covers mobile tap without hover)
  useEffect(() => {
    if (isOpen && selectedExperiment) {
      router.prefetch(selectedExperiment.href);
      if (selectedExperiment.articleHref) {
        router.prefetch(selectedExperiment.articleHref);
      }
    }
  }, [isOpen, selectedExperiment, router]);

  // Clear swipe reset timer on unmount
  useEffect(
    () => () => {
      if (swipeResetTimerRef.current) {
        clearTimeout(swipeResetTimerRef.current);
      }
    },
    []
  );

  // Track list origin for position calculations (only in list mode)
  useEffect(() => {
    if (viewMode !== "list") {
      return;
    }

    const updateOrigin = () => {
      if (listRef.current) {
        const rect = listRef.current.getBoundingClientRect();
        listOriginRef.current = { x: rect.left, y: rect.top };
      }
    };

    updateOrigin();
    window.addEventListener("resize", updateOrigin);
    window.addEventListener("scroll", updateOrigin, { passive: true });

    return () => {
      window.removeEventListener("resize", updateOrigin);
      window.removeEventListener("scroll", updateOrigin);
    };
  }, [viewMode]);

  // Start/stop lerp animation when hover state changes in list mode
  useEffect(() => {
    if (viewMode !== "list" || !isVisible) {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      isAnimatingRef.current = false;
      return;
    }

    startAnimation();

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      isAnimatingRef.current = false;
    };
  }, [viewMode, isVisible, startAnimation]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!listRef.current) {
      return;
    }
    const rect = listRef.current.getBoundingClientRect();
    mousePositionRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
    if (viewMode === "list" && isVisible && !isAnimatingRef.current) {
      startAnimation();
    }
  };

  const handleMouseEnter = (index: number) => {
    setHoveredIndex(index);
    setIsVisible(true);
    // Debounce prefetch to avoid prefetching on quick mouse pass-over
    prefetchTimeoutRef.current = setTimeout(() => {
      const exp = experiments[index];
      if (exp) {
        router.prefetch(exp.href);
        if (exp.articleHref) {
          router.prefetch(exp.articleHref);
        }
      }
      prefetchTimeoutRef.current = null;
    }, PREFETCH_HOVER_DELAY_MS);
  };

  const handleMouseLeave = () => {
    if (prefetchTimeoutRef.current) {
      clearTimeout(prefetchTimeoutRef.current);
      prefetchTimeoutRef.current = null;
    }
    setHoveredIndex(null);
    setIsVisible(false);
  };

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    touchStartRef.current = e.touches[0].clientX;
  }, []);

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent, experiment: Experiment) => {
      if (touchStartRef.current === null) {
        return;
      }

      const touchEnd = e.changedTouches[0].clientX;
      const diff = touchStartRef.current - touchEnd;
      touchStartRef.current = null;

      if (Math.abs(diff) > 50) {
        if (swipeResetTimerRef.current) {
          clearTimeout(swipeResetTimerRef.current);
          swipeResetTimerRef.current = null;
        }
        swipedExperimentSlugRef.current = experiment.slug;
        setMobilePreviewExperiment((prev) =>
          prev?.slug === experiment.slug ? null : experiment
        );
        // Fallback: clear in case synthetic click never fires
        swipeResetTimerRef.current = setTimeout(() => {
          swipedExperimentSlugRef.current = null;
          swipeResetTimerRef.current = null;
        }, 400);
      }
    },
    []
  );

  const handleExperimentClick = useCallback(
    (experiment: Experiment) => {
      if (swipedExperimentSlugRef.current === experiment.slug) {
        swipedExperimentSlugRef.current = null;
        return;
      }
      trackExperiment(UmamiEvents.EXPERIMENT_OPEN_DRAWER, {
        slug: experiment.slug,
        title: experiment.title,
      });
      setSelectedExperiment(experiment);
      setIsOpen(true);
    },
    [trackExperiment]
  );

  const handleOpenFullPage = (e?: React.MouseEvent) => {
    if (selectedExperiment) {
      trackExperiment(UmamiEvents.EXPERIMENT_OPEN_FULL, {
        slug: selectedExperiment.slug,
        title: selectedExperiment.title,
      });
      if (e && (e.metaKey || e.ctrlKey)) {
        window.open(selectedExperiment.href, "_blank");
      } else {
        router.push(selectedExperiment.href);
      }
      setIsOpen(false);
    }
  };

  const handleDrawerOpenChange = (open: boolean) => {
    if (!open && selectedExperiment) {
      track(UmamiEvents.DRAWER_CLOSE, {
        experiment_slug: selectedExperiment.slug,
      });
    }
    setIsOpen(open);
  };

  return (
    <>
      <section
        className="relative w-full space-y-6"
        onMouseMove={handleMouseMove}
        ref={listRef}
      >
        {viewMode === "list" ? (
          <div className="relative w-full">
            {/* Floating preview that follows cursor */}
            <div
              className="pointer-events-none fixed z-50 hidden overflow-hidden rounded-xl shadow-2xl md:block"
              ref={previewRef}
              style={{
                left: 0,
                top: 0,
                transform: "translate3d(0, 0, 0)",
                opacity: isVisible ? 1 : 0,
                scale: isVisible ? 1 : 0.8,
                width: "280px",
                height: "180px",
              }}
            >
              <div className="relative h-full w-full overflow-hidden rounded-xl border border-border/50 bg-background">
                {hoveredIndex !== null && experiments[hoveredIndex] && (
                  <InteractivePreviewMedia
                    experiment={experiments[hoveredIndex]}
                    isHovered={true}
                    key={experiments[hoveredIndex].slug}
                  />
                )}
              </div>
            </div>

            {/* List items */}
            <div className="relative z-10 space-y-4">
              {experiments.map((experiment, index) => (
                <ExperimentListItem
                  experiment={experiment}
                  formattedDate={formattedDates.get(experiment.slug)}
                  isMobileActive={
                    mobilePreviewExperiment?.slug === experiment.slug
                  }
                  key={experiment.slug}
                  onClick={() => handleExperimentClick(experiment)}
                  onMouseEnter={() => handleMouseEnter(index)}
                  onMouseLeave={handleMouseLeave}
                  onTouchEnd={(e) => handleTouchEnd(e, experiment)}
                  onTouchStart={handleTouchStart}
                  showTutorial={index === 0}
                />
              ))}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 items-stretch gap-6 md:grid-cols-2 md:gap-8 lg:grid-cols-3">
            {experiments.map((experiment, index) => (
              <ExperimentGridCard
                experiment={experiment}
                isMobileActive={
                  mobilePreviewExperiment?.slug === experiment.slug
                }
                key={experiment.slug}
                onClick={handleExperimentClick}
                onTouchEnd={handleTouchEnd}
                onTouchStart={handleTouchStart}
                priority={index === 0}
                showTutorial={index === 0}
              />
            ))}
          </div>
        )}

        {experiments.length === 0 && (
          <div className="rounded-lg border border-dashed p-8 text-center text-muted-foreground">
            No experiments found. Run{" "}
            <code className="rounded bg-muted px-1 py-0.5">
              npm run new:experiment
            </code>{" "}
            to create one.
          </div>
        )}
      </section>

      <ExperimentPreviewDrawer
        experiment={selectedExperiment}
        isOpen={isOpen}
        onOpenChange={handleDrawerOpenChange}
        onOpenFullPage={handleOpenFullPage}
      />
    </>
  );
}

"use client";

import { createContext, useContext } from "react";

export type CursorType = "default" | "block" | "text";

export interface CursorContextType {
  isHidden: boolean;
  pressing: boolean;
  removeSelectedElement: () => void;
  selectedElement: {
    el: HTMLElement | null;
    type: CursorType;
    config?: Record<string, unknown>;
  };
  setIsHidden: (hidden: boolean) => void;
  setSelectedElement: (element: {
    el: HTMLElement | null;
    type: CursorType;
    config?: Record<string, unknown>;
  }) => void;
  setStatus: (status: string) => void;
  status: string;
}

export const CursorContext = createContext<CursorContextType | null>(null);

const FALLBACK: CursorContextType = {
  isHidden: true,
  pressing: false,
  removeSelectedElement: () => {},
  selectedElement: { el: null, type: "default" },
  setIsHidden: () => {},
  setSelectedElement: () => {},
  setStatus: () => {},
  status: "",
};

export const useCursor = () => {
  const context = useContext(CursorContext);
  if (!context) {
    if (
      process.env.NODE_ENV === "development" &&
      typeof window !== "undefined"
    ) {
      console.warn("useCursor: no CursorProvider found, using inert fallback");
    }
    return FALLBACK;
  }
  return context;
};

"use client";

import { FileText } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type React from "react";
import { memo, useEffect, useRef, useState } from "react";
import type { Experiment } from "@/lib/experiments";
import { MobileSwipeTutorialOverlay } from "./MobileSwipeTutorialOverlay";
import { StaticExperimentMedia } from "./StaticExperimentMedia";

interface ExperimentGridCardProps {
  experiment: Experiment;
  isMobileActive: boolean;
  onClick: (e: Experiment) => void;
  onTouchEnd: (e: React.TouchEvent, experiment: Experiment) => void;
  onTouchStart: (e: React.TouchEvent) => void;
  priority?: boolean;
  showTutorial?: boolean;
}

// Grid Card Component
export const ExperimentGridCard = memo(
  ({
    experiment,
    onClick,
    onTouchStart,
    onTouchEnd,
    isMobileActive,
    showTutorial,
    priority = false,
  }: ExperimentGridCardProps) => {
    const router = useRouter();
    const [isHovered, setIsHovered] = useState(false);
    const prefetchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
      null
    );

    const PREFETCH_HOVER_DELAY_MS = 100;

    // Debounce prefetch to avoid prefetching on quick mouse pass-over
    useEffect(() => {
      if (!isHovered) {
        return;
      }

      prefetchTimeoutRef.current = setTimeout(() => {
        router.prefetch(experiment.href);
        if (experiment.articleHref) {
          router.prefetch(experiment.articleHref);
        }
        prefetchTimeoutRef.current = null;
      }, PREFETCH_HOVER_DELAY_MS);

      return () => {
        if (prefetchTimeoutRef.current) {
          clearTimeout(prefetchTimeoutRef.current);
          prefetchTimeoutRef.current = null;
        }
      };
    }, [isHovered, experiment.href, experiment.articleHref, router]);

    // Combine hover (Desktop) and mobile active state
    // For Grid, we just play the video if hovered or active.
    // No complex transitions needed, the StaticMedia component handles opacity of video vs image.
    const shouldPlay = isHovered || isMobileActive;

    return (
      <div
        className="group flex h-full cursor-pointer touch-pan-y flex-col gap-3 rounded-xl outline-hidden focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
        onClick={() => onClick(experiment)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onClick(experiment);
          }
        }}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onTouchEnd={(e) => onTouchEnd(e, experiment)}
        onTouchStart={onTouchStart}
        role="button"
        tabIndex={0}
      >
        {/* Media Container */}
        <div
          className="relative aspect-video w-full overflow-hidden rounded-xl border border-border bg-muted/30 shadow-xs transition-[border-color,box-shadow] duration-300 group-hover:border-foreground/20 group-hover:shadow-md"
          style={{ viewTransitionName: `experiment-media-${experiment.slug}` }}
        >
          <StaticExperimentMedia
            experiment={experiment}
            priority={priority}
            shouldPlay={shouldPlay}
          />
          {showTutorial && !isMobileActive && <MobileSwipeTutorialOverlay />}
        </div>

        {/* Content */}
        <div className="flex flex-1 flex-col space-y-1.5">
          <div className="flex flex-col gap-1">
            {experiment.created && (
              <span
                className="font-mono text-muted-foreground/60 text-xs"
                suppressHydrationWarning
              >
                {new Date(experiment.created).toLocaleDateString("en-US", {
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })}
              </span>
            )}
            <h3 className="font-semibold text-foreground leading-tight tracking-tight transition-colors group-hover:text-primary">
              {experiment.title}
            </h3>
          </div>
          <p className="line-clamp-3 text-pretty text-muted-foreground text-sm leading-relaxed">
            {experiment.description}
          </p>
          <div className="mt-auto flex flex-wrap items-center gap-1 pt-1">
            {experiment.tech?.map((t) => (
              <span
                className="rounded-full bg-accent px-2 py-0.5 font-medium text-[10px] text-accent-foreground"
                key={t}
              >
                {t}
              </span>
            ))}
            {experiment.articleHref && (
              <Link
                aria-label={`Read article: ${experiment.title}`}
                className="inline-flex items-center gap-1 rounded-full border border-border bg-muted/50 px-2 py-0.5 font-medium text-[10px] text-muted-foreground transition-colors hover:border-foreground/20 hover:text-foreground"
                href={experiment.articleHref}
                onClick={(e) => e.stopPropagation()}
              >
                <FileText className="h-3 w-3" />
                Article
              </Link>
            )}
          </div>
        </div>
      </div>
    );
  }
);
ExperimentGridCard.displayName = "ExperimentGridCard";

"use client";

import { FileText } from "lucide-react";
import Link from "next/link";
import React from "react";
import type { Experiment } from "@/lib/experiments";
import { InteractivePreviewMedia } from "./InteractivePreviewMedia";
import { MobileSwipeTutorialOverlay } from "./MobileSwipeTutorialOverlay";

interface ExperimentListItemProps {
  experiment: Experiment;
  formattedDate: string | undefined;
  isMobileActive: boolean;
  onClick: () => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
  onTouchEnd: (e: React.TouchEvent) => void;
  onTouchStart: (e: React.TouchEvent) => void;
  showTutorial?: boolean;
}

/**
 * A single experiment item in list view with hover preview support.
 */
export const ExperimentListItem = React.memo(function ExperimentListItem({
  experiment,
  formattedDate,
  isMobileActive,
  onMouseEnter,
  onMouseLeave,
  onClick,
  onTouchStart,
  onTouchEnd,
  showTutorial,
}: ExperimentListItemProps) {
  const [isTutorialActive, setIsTutorialActive] = React.useState(false);

  return (
    <div
      className="group relative block cursor-pointer touch-pan-y"
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      onTouchEnd={onTouchEnd}
      onTouchStart={onTouchStart}
      style={{ contentVisibility: "auto", containIntrinsicSize: "0 100px" }}
    >
      <div className="relative overflow-hidden rounded-xl border border-border bg-card p-4 transition-colors duration-300 ease-out hover:border-foreground/20 hover:bg-muted/30 md:p-6">
        {/* Mobile preview background */}
        <div
          className={`pointer-events-none absolute inset-0 z-0 transition-opacity duration-500 ${isMobileActive ? "opacity-100" : isTutorialActive ? "opacity-40 md:opacity-0" : "opacity-0"}`}
        >
          {(showTutorial || isMobileActive || isTutorialActive) && (
            <InteractivePreviewMedia
              experiment={experiment}
              forceStatic={
                (showTutorial || isTutorialActive) && !isMobileActive
              }
              isHovered={isMobileActive}
            />
          )}

          <div
            className={`absolute inset-0 bg-black/40 transition-opacity duration-300 ${isMobileActive ? "opacity-100" : "opacity-0"}`}
          />
        </div>

        {/* Content */}
        <div className="pointer-events-none relative z-10 flex flex-col items-start justify-between gap-1 md:flex-row md:gap-4">
          <div className="order-last w-full min-w-0 flex-1 md:order-first">
            <div className="mb-1">
              <h3
                className={`font-bold text-lg tracking-tight transition-colors duration-300 md:text-2xl ${isMobileActive ? "opacity-0" : "text-foreground"}`}
              >
                {experiment.title}
              </h3>
            </div>
            <p
              className={`text-[13px] leading-relaxed transition-colors duration-300 md:text-base ${isMobileActive ? "opacity-0" : "text-muted-foreground"}`}
            >
              {experiment.description}
            </p>
            <div
              className={`mt-2 flex flex-wrap items-center gap-1 transition-opacity duration-300 ${isMobileActive ? "opacity-0" : ""}`}
            >
              {experiment.tech?.map((t) => (
                <span
                  className="rounded-full bg-accent px-2 py-0.5 font-medium text-[10px] text-accent-foreground"
                  key={t}
                >
                  {t}
                </span>
              ))}
              {experiment.articleHref && (
                <Link
                  aria-label={`Read article: ${experiment.title}`}
                  className="pointer-events-auto inline-flex items-center gap-1 rounded-full border border-border bg-muted/50 px-2 py-0.5 font-medium text-[10px] text-muted-foreground transition-colors hover:border-foreground/20 hover:text-foreground"
                  href={experiment.articleHref}
                  onClick={(e) => e.stopPropagation()}
                >
                  <FileText className="h-3 w-3" />
                  Article
                </Link>
              )}
            </div>
          </div>

          {formattedDate && (
            <div className="order-first mb-0 w-full text-left md:order-last md:mb-0 md:w-auto md:text-right">
              <span
                className={`font-mono text-[11px] tabular-nums transition-colors duration-300 md:text-sm ${isMobileActive ? "opacity-0" : "text-muted-foreground opacity-60"}`}
                suppressHydrationWarning
              >
                {formattedDate}
              </span>
            </div>
          )}
        </div>
      </div>
      {showTutorial && !isMobileActive && (
        <MobileSwipeTutorialOverlay onVisibilityChange={setIsTutorialActive} />
      )}
    </div>
  );
});

"use client";

import { motion } from "motion/react";
import { useEffect, useState } from "react";

const SWIPE_GESTURE_ICON_URL = "/swipe-gesture-icon.png";

interface MobileSwipeTutorialOverlayProps {
  onVisibilityChange?: (isVisible: boolean) => void;
}

export function MobileSwipeTutorialOverlay({
  onVisibilityChange,
}: MobileSwipeTutorialOverlayProps = {}) {
  const [stage, setStage] = useState<
    "waiting" | "visible" | "exiting" | "done"
  >("waiting");

  useEffect(() => {
    onVisibilityChange?.(stage === "visible" || stage === "exiting");
  }, [stage, onVisibilityChange]);

  useEffect(() => {
    // Start sequence
    const showTimer = setTimeout(() => {
      setStage("visible");
    }, 1000);

    return () => clearTimeout(showTimer);
  }, []);

  useEffect(() => {
    if (stage === "visible") {
      const exitTimer = setTimeout(() => {
        setStage("exiting");
      }, 4000); // Stay visible for 4s
      return () => clearTimeout(exitTimer);
    }

    if (stage === "exiting") {
      const doneTimer = setTimeout(() => {
        setStage("done");
      }, 600); // Allow time for exit animation
      return () => clearTimeout(doneTimer);
    }
  }, [stage]);

  if (stage === "done") {
    return null;
  }

  const isVisible = stage === "visible";

  return (
    <motion.div
      animate={{ opacity: isVisible ? 1 : 0 }}
      aria-hidden="true"
      className="pointer-events-none absolute top-4 right-4 z-20 md:hidden"
      initial={{ opacity: 0 }}
      transition={{ duration: 0.5 }}
    >
      {/* Icon Container */}
      <motion.div className="relative rounded-md border border-border/50 bg-background/20 p-2.5 shadow-lg backdrop-blur-md">
        <motion.div
          animate={{
            x: [-3, 3, -3],
          }}
          className="relative h-5 w-5 bg-black dark:bg-white"
          style={{
